static const char *const help_0[]={"# SYSTEM / QUIET; copy ONE command line; edit numeric values as needed.","# Read current system and motor status.","@status","# Disable periodic text/CSV; this is not a motion stop.","@quiet","# Opt in to P3 probe telemetry.","@telemetry on","# Stop P3 probe telemetry.","@telemetry off","# Opt in to CSV stream.","@stream on","# Stop CSV stream.","@stream off",0};
