static const char *const help_2[]={"# MG310 MOTOR; copy ONE command line; edit numeric values as needed.","# Read actual encoder/control state.","@motor status","# Target RPM: 0..400 in current configuration.","@motor rpm 100","# Kp Ki Kd in milli-units; each 0..100000, stopped only.","@motor pid 1800 5000 0","# Explicit start; missing H-bridge/profile0 rejects.","@motor enable","# Stop and set target to zero.","@motor stop","# Request coast/wait/reverse sequence.","@motor reverse","# Clear fault without restarting.","@motor clear","# Zero count while stopped.","@motor zero","# One EC11 detent: +5 RPM, saturates at maximum.","@knob 1","# One reverse EC11 detent: -5 RPM, saturates at zero.","@knob -1","# 50Hz JustFloat on HOST; no motor start. USB keeps text replies.","@motor plot on","# Stop motor wave stream; return HOST to text.","@motor plot off","# Plot state/counters. While plotting, read response on USB.","@motor plot status","# Disable power output and retain selected RPM for restart.","@motor disable","# KEY7 motor knob button: short release toggles enable; driver0 refuses start.","@key 7 tap","# Motor button: hold >=1000ms reverses once; no enable toggle.","@key 7 press 1200","# Same knob path: +5 RPM, bounded 0..400.","@knob 1","# Same knob path: -5 RPM, bounded 0..400.","@knob -1","# Set 400 RPM only; does not start motor.","@motor rpm 400",0};
static const char *const help_3[]={"# CAMERA / IMAGE; copy ONE command line; edit numeric values as needed.","# Enable capture; enter Image viewer to display.","@camera on","# Stop capture.","@camera off","# Next complete frame frozen in RAM; no SD/JPEG file.","@camera shot","# Resume continuous capture.","@camera live","# Rotate displayed image +90 degrees.","@camera rotate","# Toggle horizontal mirror.","@camera mirror","# Toggle vertical flip.","@camera flip","# Gradient edge preview only.","@camera edge on","# RGB preview.","@camera edge off","# LCD text orientation +90 independently.","@lcd rotate","# Reinitialize sensor while motion stopped.","@camera retry","# OV5640 divider: 0,1,2,4,8,16; stopped only.","@camera clock 4","# LCD test pattern; next menu gesture restores menu.","@lcd test","# Enable versioned RGB565 frames on USB only; UART1 remains control.","@video on","# Stop image transfer and clear advisory; not a motor stop.","@video off","# Upper frame-rate limit 1..5; default 2, actual rate depends on USB and capture.","@video fps 2","# Read video counters and latest advisory validity.","@video status","# Read pixel-only grasp advisory; no actuator execution.","@vision status","# Invalidate pixel grasp advisory; does not stop an already commanded actuator.","@vision clear",0};
