static const char *const help_7[]={"# KEYS / EC11; copy ONE command line; edit numeric values as needed.","# Read six menu/claw keys, source masks and mode.","@input status","# Physical and remote OR; release keys/stop motion before changing.","@input mode mixed","# Use physical keys only.","@input mode physical","# Ignore physical keys; real Hall feedback remains real.","@input mode remote","# Screen UP / decrement.","@key 1 tap","# Screen DOWN / increment.","@key 2 tap","# Screen CONFIRM.","@key 3 tap","# Screen CANCEL / back.","@key 4 tap","# K3+K4 shortcut to DEBUG grants page / return to previous page.","@keys 12 100","# Claw A0 gesture; offline requests reprobe.","@key 5 tap","# Claw A0 hold; requires calibrated/safe state.","@key 5 press 3500","# Claw B0 hold and release; may scan if online.","@key 6 hold","# K5+K6: claw mechanical calibration gesture.","@keys 48 3500","# KEY7 motor knob button: short release toggles enable; driver0 refuses start.","@key 7 tap","# KEY7 hold >=1000ms reverses once; release does not toggle enable.","@key 7 press 1200","# Keep simulated confirm down; release generates action.","@key 3 down","# Release this source confirm; not an emergency stop.","@key 3 up","# Release this source only; release may complete a click.","@keys release","# Simulate one forward EC11 detent.","@knob 1","# Simulate one reverse EC11 detent.","@knob -1","# Read independent runtime key grants; boot OFF.","@debug status","# Grant STS key gestures; does not start motion; release K5..7 first.","@debug sts on","# Revoke STS keys only; does not stop an existing motion.","@debug sts off","# Grant K5 start/stop, K6 single -5 / double +5 RPM, knob and K7.","@debug motor on","# Revoke motor keys only; use @motor disable to stop output.","@debug motor off",0};
